<div class="section-head"><div><span class="eyebrow">INSIGHT & EXPORT</span><h2>Laporan Pembelajaran</h2><p class="muted">Gunakan filter untuk meninjau hasil belajar dan rekomendasi.</p></div><div><a class="btn secondary" href="export.php?format=csv&type=<?=e($reportType)?>">Export Excel/CSV</a> <a class="btn secondary" href="export.php?format=pdf&type=<?=e($reportType)?>">Export PDF</a> <button class="btn secondary" onclick="window.print()">Cetak</button></div></div><div class="filter-tabs"><a class="<?=$reportType==='summary'?'active':''?>" href="<?=url('reports')?>&type=summary">Semua</a><a class="<?=$reportType==='remedial'?'active':''?>" href="<?=url('reports')?>&type=remedial">Remedial</a><a class="<?=$reportType==='pengayaan'?'active':''?>" href="<?=url('reports')?>&type=pengayaan">Pengayaan</a><a class="<?=$reportType==='kelas'?'active':''?>" href="<?=url('reports')?>&type=kelas">Per Kelas</a></div><div class="table-card"><table><thead><tr><th>Siswa</th><th>Kelas</th><th>Mapel</th><th>Nilai</th><th>Kehadiran</th><th>Status</th><th>Rekomendasi AI</th><th></th></tr></thead><tbody><?php foreach($reports as $r): if($reportType==='remedial'&&$r['action_label']!=='Remedial')continue; if($reportType==='pengayaan'&&$r['action_label']!=='Pengayaan')continue; ?><tr><td><b><?=e($r['name'])?></b><br><small><?=e($r['nis'])?></small></td><td><?=e($r['class_name'])?></td><td><?=e($r['subject'])?></td><td><b><?=number_format((float)$r['avg_score'],1)?></b></td><td><?=number_format((float)$r['attendance_rate'],0)?>%</td><td><span class="badge <?=$r['avg_score']>=75?'success':'danger'?>"><?=$r['avg_score']>=75?'Tuntas':'Belum Tuntas'?></span></td><td><span class="badge <?=badgeClass($r['action_label']??'')?>"><?=e($r['action_label']??'Belum dianalisis')?></span></td><td><a class="text-link" href="<?=url('profile')?>&id=<?=e($r['student_id'])?>">Profil</a></td></tr><?php endforeach;?></tbody></table></div>